INSERT INTO public.exercises (subject_id, title, type, difficulty, statement, correction) SELECT s.id, 'IHD Ch1 Ex1', 'dissertation', 'moyen', 'Pourquoi loi XII Tables est-elle importante dans histoire droit ?', 'Loi XII Tables (450 av JC) : première codification écrite droit romain. Crée égalité formelle : lois publiques pas secrètes. Limite pouvoir discrétionnaire. Devient référence Antiquité. Établit principe : État doit avoir lois écrites accessibles.' FROM public.subjects s WHERE s.slug = 'introduction-historique-au-droit' AND NOT EXISTS (SELECT 1 FROM public.exercises e WHERE e.subject_id = s.id AND e.title = 'IHD Ch1 Ex1');
INSERT INTO public.exercises (subject_id, title, type, difficulty, statement, correction) SELECT s.id, 'IHD Ch1 Ex2', 'dissertation', 'moyen', 'Quel était apport majeur Corpus juris civilis ?', 'Corpus juris civilis (VIe s.) compile systématiquement droit romain : constitutions impériales, sénatus-consultes, jurisprudence. Rationalise organisation hiérarchique. Apport : préserve droit romain, devient référence universelle. Tous droits civils modernes s''en inspirent.' FROM public.subjects s WHERE s.slug = 'introduction-historique-au-droit' AND NOT EXISTS (SELECT 1 FROM public.exercises e WHERE e.subject_id = s.id AND e.title = 'IHD Ch1 Ex2');
INSERT INTO public.exercises (subject_id, title, type, difficulty, statement, correction) SELECT s.id, 'IHD Ch1 Ex3', 'dissertation', 'difficile', 'Comment droit romain a-t-il influencé droits modernes ? Donnez exemples précis.', 'Droit romain influencé : 1) concept propriété (droit absolu) 2) droit contrats obligations 3) organisation judiciaire 4) notion État droit 5) sources droit (codes codifiés). Exemples : Code Napoléon, droit français civil, droit allemand. Droit romain = fondement intellectuel systèmes juridiques occidentaux.' FROM public.subjects s WHERE s.slug = 'introduction-historique-au-droit' AND NOT EXISTS (SELECT 1 FROM public.exercises e WHERE e.subject_id = s.id AND e.title = 'IHD Ch1 Ex3');
