-- Migration 036: Introduction historique au droit - Ch1

SELECT s.id, 'IHD — L''Antiquité', 'Chapitre 1 - L''Antiquité', 'moyen',
  '[{"question":"Qu''est-ce que droit romain classique ?","choices":["A. Droit Moyen Âge","B. Système juridique Rome antique (IIe-IIIe s.)","C. Droit français","D. Droit grec"],"correct_index":1,"explanation":"Droit romain classique : droit Rome antique développé aux 2e et 3e siècles."},{"question":"Quel était principal recueil droit romain ?","choices":["A. Lois coutumières","B. Corpus juris civilis Justinien","C. Code Napoléon","D. Constitutions impériales"],"correct_index":1,"explanation":"Corpus juris civilis (VIe s.) : compilation systématique droit romain, référence universelle."},{"question":"Qu''est-ce que loi XII Tables ?","choices":["A. Traité international","B. Premier code écrit droit romain (450 av JC)","C. Loi médiévale","D. Commentaire juridique"],"correct_index":1,"explanation":"Loi XII Tables (450 av JC) : première codification écrite droit romain."},{"question":"Qu''est-ce que droit civil romain ?","choices":["A. Droit international","B. Droit applicable aux citoyens romains","C. Droit étrangers","D. Droit commercial"],"correct_index":1,"explanation":"Droit civil (ius civile) : régissait relations citoyens romains."},{"question":"Qu''est-ce que droit des gens romain ?","choices":["A. Droit peuple","B. Droit applicable à tous, citoyens étrangers","C. Droit international","D. Droit public"],"correct_index":1,"explanation":"Droit des gens (ius gentium) : s''appliquait universellement."},{"question":"Qui était jurisconsulte romain ?","choices":["A. Juge","B. Expert en droit dont avis guidaient juges","C. Législateur","D. Politicien"],"correct_index":1,"explanation":"Jurisconsultes romains : experts droit, avis guidaient pratique judiciaire."},{"question":"Quel était rôle Empereur dans création droit ?","choices":["A. Aucun rôle","B. Interpréter loi","C. Émettre constitutions impériales force loi","D. Seulement administrer"],"correct_index":2,"explanation":"Empereur édictait constitutions (lois impériales) sources majeures droit."},{"question":"Qu''est-ce qu''une constitution impériale romaine ?","choices":["A. Loi électorale","B. Édit Empereur force loi","C. Ordonnance locale","D. Charte commerciale"],"correct_index":1,"explanation":"Constitution impériale : édit Empereur valeur loi."},{"question":"Quel était rôle Sénat romain en matière juridique ?","choices":["A. Émettre lois principales","B. Émettre sénatus-consultes (actes législatifs)","C. Juger affaires","D. Aucun rôle"],"correct_index":1,"explanation":"Sénatus-consultes : délibérations Sénat force loi."},{"question":"Comment droit romain s''appliquait-il hors Rome ?","choices":["A. Ne s''appliquait pas","B. S''imposait graduellement avec expansion romaine","C. Seulement aux élites","D. Jamais"],"correct_index":1,"explanation":"Avec conquête romaine, droit romain s''imposa progressivement provinces."},{"question":"Qu''est-ce que propriété en droit romain ?","choices":["A. Simple usage bien","B. Droit absolu, exclusif perpétuel sur chose","C. Location","D. Droit communal"],"correct_index":1,"explanation":"Propriété romaine : pouvoir le plus complet et absolu sur une chose."},{"question":"Quel était statut esclaves en droit romain ?","choices":["A. Citoyens","B. Res (choses), sans droits juridiques","C. Demi-citoyens","D. Propriétaires"],"correct_index":1,"explanation":"Esclaves : aucun statut juridique, considérés comme choses."},{"question":"Qu''est-ce que patria potestas romaine ?","choices":["A. Pouvoir roi","B. Pouvoir absolu père famille sur membres","C. Pouvoir municipal","D. Pouvoir religieux"],"correct_index":1,"explanation":"Patria potestas : autorité absolue pater familias sur ménage."},{"question":"Comment droit romain s''transmis au Moyen Âge ?","choices":["A. Ne s''transmis pas","B. Par tradition, textes, études XIIe siècle","C. Par voie orale","D. Seulement en Italie"],"correct_index":1,"explanation":"Après Rome, droit survit textes (Corpus Justinien) pratique ecclésiale."},{"question":"Qu''était droit des actions en droit romain ?","choices":["A. Droits civils","B. Procédures défendre ses droits en justice","C. Lois civiles","D. Décrets impériaux"],"correct_index":1,"explanation":"Actions (ius actionis) : voies procédurales revendiquer droit."},{"question":"Quelle était importance droit romain pour monde occidental ?","choices":["A. Très faible","B. Fondamentale : a modelé tous systèmes juridiques modernes","C. Seulement antique","D. Seulement religieuse"],"correct_index":1,"explanation":"Droit romain fondamental : influencé directement plupart droits civils modernes."},{"question":"Qui était Justinien et quel était son apport ?","choices":["A. Juge Moyen Âge","B. Empereur byzantin qui compila Corpus juris civilis","C. Législateur français","D. Philosophe grec"],"correct_index":1,"explanation":"Justinien (VIe s.) : ordonna compilation systématique droit romain."},{"question":"Qu''est-ce que Digeste dans Corpus juris ?","choices":["A. Constitutions impériales","B. Compilation jurisprudences opinions juristes","C. Lois Sénat","D. Traités commerciaux"],"correct_index":1,"explanation":"Digeste : recueille extraits écrits grands juristes romains."},{"question":"Quel était code social romain fondamental ?","choices":["A. Loi XII Tables seule","B. Ensemble droit civil, droit des gens, constitutions","C. Coutumes uniquement","D. Lois religieuses"],"correct_index":1,"explanation":"Système juridique romain : hiérarchisé, intégrait sources multiples autorité."},{"question":"Comment Rome a-t-elle influencé droits modernes ?","choices":["A. Pas d''influence","B. Par concept propriété, contrats, organisation judiciaire","C. Seulement antique","D. Seulement politique"],"correct_index":1,"explanation":"Rome influencé : propriété, contrats, obligations, organisation judiciaire, droit civil."}]'::jsonb
FROM public.subjects s
WHERE s.slug = 'introduction-historique-au-droit'
AND NOT EXISTS (SELECT 1 FROM public.quizzes q WHERE q.subject_id = s.id AND q.chapter = 'Chapitre 1 - L''Antiquité');




